<?php
require_once __DIR__.'/sesion_segura.php';iniciar_sesion_segura();if(empty($_SESSION['usuario'])){header('Location: ./login.php');exit();}require_once './csrf.php';require_once './conexion.php';require_once './validacion_calidad.php';require_once './alertify_error.php';$id=filter_var($_GET['id']??null,FILTER_VALIDATE_INT);if(!$id||$id<1)redirigir_error_alertify('El identificador del control no es válido.');$db=conexion();$stmt=$db->prepare('SELECT * FROM controles_calidad WHERE id=?');$stmt->bind_param('i',$id);$stmt->execute();$control=$stmt->get_result()->fetch_assoc();$stmt->close();if(!$control){$db->close();redirigir_error_alertify('El control solicitado no existe.',404);}
$cosechas=$db->query('SELECT c.id,c.codigo_cosecha,v.nombre AS variedad FROM cosechas c INNER JOIN lotes_cultivo lc ON lc.id=c.lote_id INNER JOIN variedades v ON v.id=lc.variedad_id ORDER BY c.fecha_cosecha DESC')->fetch_all(MYSQLI_ASSOC);$productos=$db->query('SELECT id,cosecha_id,codigo_qr,tipo_producto FROM inventario_derivado ORDER BY id DESC')->fetch_all(MYSQLI_ASSOC);$db->close();$tipos=['Humedad','Inspección visual','Contaminantes','Análisis de laboratorio','Otro'];$resultados=['Pendiente','Conforme','No conforme'];
