<!DOCTYPE html><html lang="es"><head><?php include 'head.php';?></head><body class="ui-bg-2"><?php include 'loader.php';include 'index_nav.php';?><form action="control_calidad_actualizar.php" method="post"><?= campo_token_csrf() ?><input type="hidden" name="id" value="<?= (int)$id ?>"><nav class="navbar expand navbar-dark"><div class="container-lg px-3"><a class="navbar-brand" href="control_calidad.php">Volver a controles</a><button class="btn-nav btn btn-dark" type="submit" title="Guardar cambios"><i class="fa-light fa-floppy-disk"></i></button></div></nav><main class="container pb-4"><div class="row justify-content-center"><div class="col-lg-8"><div class="card p-4"><h4 class="mb-3">Editar control de calidad</h4>
<div class="mb-3"><label class="form-label" for="cosecha_id">Cosecha</label><select class="form-select" name="cosecha_id" id="cosecha_id" required><?php foreach($cosechas as $c):?><option value="<?= (int)$c['id'] ?>" <?= (int)$control['cosecha_id']===(int)$c['id']?'selected':'' ?>><?= htmlspecialchars($c['codigo_cosecha'].' · '.$c['variedad'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach;?></select></div><div class="mb-3"><label class="form-label" for="inventario_derivado_id">Producto derivado (opcional)</label><select class="form-select" name="inventario_derivado_id" id="inventario_derivado_id"><option value="">Control de la cosecha completa</option><?php foreach($productos as $p):?><option value="<?= (int)$p['id'] ?>" data-cosecha="<?= (int)$p['cosecha_id'] ?>" <?= (int)$control['inventario_derivado_id']===(int)$p['id']?'selected':'' ?>><?= htmlspecialchars($p['codigo_qr'].' · '.$p['tipo_producto'],ENT_QUOTES,'UTF-8') ?></option><?php endforeach;?></select></div>
<div class="row"><div class="col-md-6 mb-3"><label class="form-label" for="tipo_control">Tipo de control</label><select class="form-select" name="tipo_control" id="tipo_control"><?php foreach($tipos as $op):?><option <?= $control['tipo_control']===$op?'selected':'' ?>><?= htmlspecialchars($op,ENT_QUOTES,'UTF-8') ?></option><?php endforeach;?></select></div><div class="col-md-6 mb-3"><label class="form-label" for="fecha_control">Fecha</label><input class="form-control" type="date" name="fecha_control" id="fecha_control" value="<?= htmlspecialchars($control['fecha_control'],ENT_QUOTES,'UTF-8') ?>" required></div></div><div class="row"><div class="col-md-4 mb-3"><label class="form-label" for="resultado">Resultado</label><select class="form-select" name="resultado" id="resultado"><?php foreach($resultados as $op):?><option <?= $control['resultado']===$op?'selected':'' ?>><?= htmlspecialchars($op,ENT_QUOTES,'UTF-8') ?></option><?php endforeach;?></select></div><div class="col-md-4 mb-3"><label class="form-label" for="valor">Medición</label><input class="form-control" type="number" min="0" max="9999999.999" step="0.001" name="valor" id="valor" value="<?= htmlspecialchars(formatear_valor_calidad($control['valor'],'.'),ENT_QUOTES,'UTF-8') ?>"></div><div class="col-md-4 mb-3"><label class="form-label" for="unidad">Unidad</label><input class="form-control" maxlength="20" name="unidad" id="unidad" value="<?= htmlspecialchars((string)$control['unidad'],ENT_QUOTES,'UTF-8') ?>"></div></div><div class="mb-3"><label class="form-label" for="observaciones">Observaciones</label><textarea class="form-control" name="observaciones" id="observaciones" maxlength="1000" rows="4"><?= htmlspecialchars((string)$control['observaciones'],ENT_QUOTES,'UTF-8') ?></textarea></div></div></div></div></main></form><script>const cosecha=document.getElementById('cosecha_id'),producto=document.getElementById('inventario_derivado_id');if(cosecha&&producto){function filtrarProductos(){for(const opcion of producto.options){if(!opcion.value){opcion.hidden=false;continue;}opcion.hidden=opcion.dataset.cosecha!==cosecha.value;if(opcion.hidden&&opcion.selected)producto.value='';}}cosecha.addEventListener('change',filtrarProductos);filtrarProductos();}</script><script>
        document.body.style.overflow = "hidden";

        $(document).ready(function() {
            function ocultarLoader() {
                $(".ui-loader").fadeOut(function() {
                    $(".ui-loader-bg").fadeOut().addClass("sale");
                    document.body.style.overflow = "auto";
                });
            }

            setTimeout(ocultarLoader, 250);

            window.addEventListener('pageshow', function(event) {
                if (event.persisted) {
                    ocultarLoader();
                    $("a").css("pointer-events", "auto");
                }
            });
        });
    </script></body></html>
